const item = $input.first().json;

// Localiza o CSV recebido pelo HTTP Request
const csvRaw =
  item.data ??
  item.body ??
  item.text ??
  item;

let csv;

if (typeof csvRaw === 'string') {
  csv = csvRaw;
} else {
  throw new Error(
    'O CSV não chegou como texto. Verifique o formato de resposta do HTTP Request.'
  );
}

// Divide o CSV em linhas
const lines = csv
  .replace(/^\uFEFF/, '')
  .trim()
  .split(/\r?\n/)
  .filter(line => line.trim() !== '');

if (lines.length < 2) {
  throw new Error('O CSV precisa ter cabeçalho e pelo menos uma linha de dados.');
}

// Detecta o separador mais provável
const separadores = [',', ';', '\t'];
const separador = separadores.reduce((melhor, atual) =>
  (lines[0].split(atual).length >
   lines[0].split(melhor).length) ? atual : melhor
);

// Divide campos respeitando aspas e vírgulas dentro delas
function separarLinha(linha, sep) {
  const resultado = [];
  let campo = '';
  let aspas = false;

  for (let i = 0; i < linha.length; i++) {
    const c = linha[i];

    if (c === '"') {
      if (aspas && linha[i + 1] === '"') {
        campo += '"';
        i++;
      } else {
        aspas = !aspas;
      }
    } else if (c === sep && !aspas) {
      resultado.push(campo.trim());
      campo = '';
    } else {
      campo += c;
    }
  }

  resultado.push(campo.trim());
  return resultado;
}

// Padroniza os nomes das colunas
const headers = separarLinha(lines[0], separador)
  .map(h => h.trim().replace(/^"|"$/g, ''));

const clientes = lines.slice(1).map((linha, index) => {
  const colunas = separarLinha(linha, separador);
  const cliente = {};

  headers.forEach((header, i) => {
    cliente[header] = colunas[i] ?? '';
  });

  return { json: cliente };
});

return clientes;

const entrada = $input.all();
const resultado = [];

// Separa os dados dos clientes e os parâmetros de investimento
let clientes = [];
let investimento = {};

for (const item of entrada) {
  const dados = item.json;

  if (Array.isArray(dados.body?.clientes)) {
    clientes.push(...dados.body.clientes);
  } else if (Array.isArray(dados.clientes)) {
    clientes.push(...dados.clientes);
  } else if (dados.nome && dados.email) {
    clientes.push(dados);
  }

  // Parâmetros recebidos do fluxo de investimento
  if (dados.produto !== undefined) {
    investimento.produto = dados.produto;
  }

  if (dados.minimo !== undefined) {
    investimento.minimo = dados.minimo;
  }

  if (dados.rentabilidade !== undefined) {
    investimento.rentabilidade = dados.rentabilidade;
  }
}

// Cria uma mensagem personalizada para cada cliente
for (const cliente of clientes) {
  const perfil = cliente.perfil ?? 'Não informado';

  let foco;

  if (perfil === 'Conservador') {
    foco = 'preservação do patrimônio e previsibilidade';
  } else if (perfil === 'Moderado') {
    foco = 'equilíbrio entre segurança e crescimento';
  } else if (perfil === 'Arrojado') {
    foco = 'crescimento patrimonial e maior tolerância a riscos';
  } else {
    foco = 'avaliação de alternativas compatíveis com seu perfil';
  }

  const mensagem = [
    `Olá, ${cliente.nome}!`,
    '',
    `Seu perfil de investidor é ${perfil}.`,
    `Seu saldo informado é ${cliente.saldo ?? 'Não informado'}.`,
    '',
    `Nosso foco para você é ${foco}.`,
    '',
    `Investimento disponível: ${investimento.produto ?? 'Não informado'}.`,
    `Valor mínimo informado: ${investimento.minimo ?? 'Não informado'}.`,
    `Rentabilidade informada: ${investimento.rentabilidade ?? 'Não informada'}.`,
    '',
    'Avalie os riscos, os custos e a liquidez antes de investir.'
  ].join('\n');

  resultado.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil,
      produto_investimento: investimento.produto ?? null,
      valor_minimo: investimento.minimo ?? null,
      rentabilidade: investimento.rentabilidade ?? null,
      mensagem_personalizada: mensagem
    }
  });
}

return resultado;

const entrada = $input.all();

return entrada.map((item, index) => {
  const cliente = item.json;

  return {
    json: {
      numero: index + 1,
      nome: cliente.nome ?? '',
      email: cliente.email ?? '',
      perfil: cliente.perfil ?? '',
      saldo: cliente.saldo ?? '',
      produto_investimento: cliente.produto_investimento ?? '',
      valor_minimo: cliente.valor_minimo ?? '',
      rentabilidade: cliente.rentabilidade ?? '',
      foco: cliente.perfil === 'Conservador'
        ? 'Preservação do patrimônio e previsibilidade'
        : cliente.perfil === 'Moderado'
          ? 'Equilíbrio entre segurança e crescimento'
          : cliente.perfil === 'Arrojado'
            ? 'Crescimento patrimonial e tolerância a riscos'
            : 'Perfil a avaliar',
      mensagem_personalizada: cliente.mensagem_personalizada ?? '',
      status: 'Pendente de análise do agente'
    }
  };
});
